INSERT INTO public.dual_scenarios (pool, category, sub_theme, scene, attire, disabled, day_of, relationship_scope) VALUES ('holiday', 'halloween', 'swamp_witch_bayou', 'Flooded cemetery at swamp edge, headstones draped in Spanish moss, carved jack-o-lanterns perched atop every grave glowing amber-green, still black water reflecting violet clouds, will-o-wisps hovering above sunken plots, fireflies weaving between stones', 'She in charcoal silk chemise gown with layered black petticoats and a wide obsidian-beaded collar, he in a tailored black swallowtail coat with bone-button vest and tall hat', false, false, 'any');
INSERT INTO public.dual_scenarios (pool, category, sub_theme, scene, attire, disabled, day_of, relationship_scope) VALUES ('holiday', 'halloween', 'swamp_witch_bayou', 'Rope bridge swaying over foggy bayou channel, carved grinning lanterns tied at every post, Spanish moss hanging like curtains below the boards, will-o-wisps drifting beneath, cypress canopy closing overhead, crescent moon barely visible through branches', 'She in deep teal ruffled blouse with a corseted vest and silver serpent arm cuff, he in belted riding coat with brass-buckled straps and a weathered flat-brim hat', false, false, 'any');
INSERT INTO public.holiday_scenes (holiday, sub_theme, scene, disabled, day_of) VALUES ('halloween', 'graveyard_picnic', 'Dozens of jack-o-lanterns rise slowly from the soil between tombstones, their carved faces glowing amber and crimson as they float upward like harvest balloons tethered to nothing. They arrange themselves in concentric rings above the checkered blanket, illuminating the picnic spread below in warm flickering geometry. The blood moon hangs enormous behind them, and silver fog threads between the suspended pumpkins, carrying the faint warm scent of scorched gourd through the cold cemetery air.', false, false);
INSERT INTO public.holiday_scenes (holiday, sub_theme, scene, disabled, day_of) VALUES ('halloween', 'haunted_mansion', 'A river of silver fog pours steadily down the mansion''s grand staircase visible through the open front door, pooling on the veranda and spilling over the steps like a slow waterfall. Embedded within the fog, dozens of antique clocks tick and float at different heights, each frozen at a different midnight, their pendulums swinging in opposite directions while moth-winged spirits drift between them carrying thimbles of golden light.', false, false);
INSERT INTO public.holiday_scenes (holiday, sub_theme, scene, disabled, day_of) VALUES ('halloween', 'haunted_mansion', 'The mansion''s widow''s walk at the roofline is crowded with jack-o-lanterns of every conceivable shape, their carved faces shifting expressions when observed from different angles—grinning to grimacing to winking. A vast spiderweb connects all four chimneys, its silk threads strung with dewdrops that refract the copper moonlight into tiny prismatic specters, and a single enormous shadow moves steadily across the web from within, though no spider is visible.', false, false);
INSERT INTO public.holiday_scenes (holiday, sub_theme, scene, disabled, day_of) VALUES ('halloween', 'headless_hollow_bridge', 'Jack-o-lanterns line every inch of the hollow bridge''s railing, each carved with a different grimacing face, their amber light smearing across the creek''s black water below. Thick fog rolls through in slow, deliberate waves, briefly swallowing entire rows of glowing faces before retreating. Overhead, a murder of crows spirals downward in a tight gyre, feathers catching the blood moon''s copper light like falling coins.', false, false);
INSERT INTO public.holiday_scenes (holiday, sub_theme, scene, disabled, day_of) VALUES ('halloween', 'headless_hollow_bridge', 'Frost has seized the hollow bridge overnight, coating every plank and beam in glass-clear ice that refracts the blood moon into a thousand small red moons scattered across the fog. A lone will-o''-wisp bobs at the bridge''s far mouth, pulsing amber then green then bone-white, casting long prismatic shadows down the tunnel. Bare willows on both banks trail their frozen fingers into still black water, perfectly motionless.', false, false);
